def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        from datetime import timezone, timedelta, datetime
        if tz is None:
            tz = timezone.utc
        elif isinstance(tz, str):
            tz = timezone(timedelta(hours=int(tz)))
        elif not isinstance(tz, timezone):
            raise ValueError("tz must be None, a string representing hours offset, or a datetime.timezone object")

        seconds, nanoseconds = divmod(nanoseconds, 1_000_000_000)
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
        days, hours = divmod(hours, 24)

        # Assuming the nanoseconds are since epoch
        dt = datetime(1970, 1, 1, hour=0, minute=0, second=0, microsecond=0, tzinfo=timezone.utc) + timedelta(days=days, hours=hours, minutes=minutes, seconds=seconds, microseconds=nanoseconds // 1000)
        return dt.astimezone(tz)
    except Exception as e:
        raise ValueError(f"Error hydrating time: {e}")

