def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import os
    from concurrent.futures import ThreadPoolExecutor

    if target_concurrency < 1:
        raise ValueError("target_concurrency must be at least 1")

    def _run_command(args: Sequence[str]) -> tuple[int, bytes]:
        full_cmd = cmd + tuple(args)
        try:
            if color and os.name != 'nt':
                return subprocess.run(
                    full_cmd, check=True, capture_output=True, text=False, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, bufsize=1, universal_newlines=False, shell=False, env=None, cwd=None, timeout=None, input=None, shell=False, pty=True, **kwargs
                )
            else:
                return subprocess.run(
                    full_cmd, check=True, capture_output=True, text=False, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE, **kwargs
                )
        except subprocess.CalledProcessError as e:
            return e.returncode, e.stderr

    def _chunk_varargs(varargs: Sequence[str], max_length: int, cmd: tuple[str, ...]) -> list[list[str]]:
        chunk = []
        chunks = []
        cmd_length = sum(len(arg) + 1 for arg in cmd)  # +1 for space
        for arg in varargs:
            arg_length = len(arg) + 1  # +1 for space
            if cmd_length + sum(len(a) + 1 for a in chunk) + arg_length > max_length:
                chunks.append(chunk)
                chunk = []
            chunk.append(arg)
        if chunk:
            chunks.append(chunk)
        return chunks

    chunks = _chunk_varargs(varargs, _max_length, cmd)
    with ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        results = list(executor.map(_run_command, chunks))

    exit_codes, outputs = zip(*results)
    final_output = b''.join(outputs)
    if any(code != 0 for code in exit_codes):
        raise subprocess.CalledProcessError(returncode=max(exit_codes), cmd=cmd, output=final_output)
    return 0, final_output

